function choice(key, prompt, correct, distractors, explanation, figure) {
  const options = [...distractors];
  const answer = [...key].reduce((sum, character) => sum + character.charCodeAt(0), 0) % 4;
  options.splice(answer, 0, correct);
  return { key, prompt, options, answer, explanation, ...(figure && { figure }) };
}

function numeric(key, prompt, parts, explanation, figure) {
  return { key, prompt, parts, explanation, ...(figure && { figure }) };
}

function part(label, answer, tolerance = 0, unit = '') {
  return { label, answer, tolerance, unit };
}

function table(caption, headers, rows) {
  return { caption, headers, rows };
}

function drawing(caption, alt, content) {
  return {
    caption,
    alt,
    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 220" fill="none" stroke="#23314d" stroke-width="2">' +
      content.replaceAll('<text ', '<text fill="#23314d" stroke="none" font-family="system-ui, sans-serif" font-size="15" ') +
      '</svg>',
  };
}

function topic(number, simple, challenge) {
  const bank = 'mathematics-3.' + number;
  const entries = (items, level) => items.map(({ key, ...item }) => ({
    id: 'math-3-' + number + '-' + key,
    bank,
    level,
    ...item,
  }));
  return [...entries(simple, 'simple'), ...entries(challenge, 'challenge')];
}

